// sql-injection-reviewed-file: disposable-cluster TEST HARNESS (database layer), never request-path code. Every DDL interpolation is an identifier generated by this harness (`obc_<tag>_<run>`, `crewflow_owner`, the schema role names, generated database names) passed through ident(), which accepts only ^[a-z_][a-z0-9_]{0,62}$ and double-quotes it; role attributes are code literals checked against ^[A-Z]+$; OWNER_CREATEROLE_MARK_PREFIX is a quote-free code constant and every mark expiry offset is a code integer; ${label} is an assertion message, not SQL; passwords and verifiers go only as $n bind parameters. Reviewed 2026-11-18 (db-setup the Twenty way).
/**
 * Database setup the Twenty way (owner decision 2026-11-18): the real-database harness of the bootstrap child. The child
 * reads PG_DATABASE_URL (ALWAYS crewflow_owner, its password from the environment, the very URL rab-api and rab-worker use)
 * and, in modes a / b, PG_ADMIN_URL; it writes no file. Disposable loopback PostgreSQL ONLY (crewflow.disposable_cluster=on).
 * It spawns the REAL child (bootstrap-owner-login, dist when built, else the source through ts-node) as a separate process
 * with only its database URLs (no APP_SECRET), and asserts the database state read as the cluster superuser, never the exit
 * code alone. The CREATEROLE lifecycle scenario also runs the REAL migrate child (twenty-migrate.ts) and the boot gate's
 * CREATEROLE rule (database-boot-gate-rules.ts assertCreateRoleGate) on a crewflow_owner session. The db-harden scenarios run the
 * REAL child with `--harden` (owner decision M1), one of them in the background while the real migrate child runs.
 *
 *   MIGRATION_SECURITY_ADMIN_URL=<superuser of a DISPOSABLE loopback cluster> \
 *   [OWNER_BOOTSTRAP_PG_CONTAINER=<docker container of that cluster, started with -c log_statement=all>] \
 *     ts-node --transpile-only -P packages/rab-server/tsconfig.app.json \
 *       packages/rab-server/src/database/typeorm/scripts/owner-login/bootstrap-owner-login-check.ts [--source] [--report <file.json>]
 *
 * On a PostgreSQL 15 cluster it runs only the PG15 refusal; on 16+ every other scenario. crewflow_owner is CLUSTER-wide, so
 * scenarios run one after another and each starts from no crewflow_owner. The harness refuses a cluster that already has a
 * crewflow_owner it did not create.
 *
 * Secrets are generated here (random per run) and never printed: every child's stdout+stderr, and (with
 * OWNER_BOOTSTRAP_PG_CONTAINER) the server log, are searched for them in memory. rolpassword is compared by SHA-256 only.
 * Output: scenario ids, PASS/FAIL, counts.
 */
import { spawn, spawnSync } from 'node:child_process';
import { createHash, randomBytes } from 'node:crypto';
import { existsSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

import { assertCreateRoleGate, BOOT_FACTS_SQL, DatabaseBootGateError, parseBootFacts } from '../../../boot-checks/database-boot-gate-rules';
import { OWNER_CREATEROLE_GRACE_SECONDS, OWNER_CREATEROLE_MARK_PREFIX } from '../../../boot-checks/owner-login-posture';
import { DB_SETUP_INPUT_MESSAGES, isStrongOwnerPassword, scramSha256Verifier } from '../../../owner-login/owner-credential';
import { createPgClientForUrl, resolvePgEnvironment } from '../../../postgres';
import {
  bootstrapDriverConfigs,
  connectSession,
  imageMigrationNames,
  OWNER_BOOTSTRAP_MESSAGES,
  OWNER_BOOTSTRAP_RESULT_PREFIX,
  OwnerBootstrapResult,
} from './owner-bootstrap';
import { OWNER_BOOTSTRAP_Q4B_SET_INPUTS, OWNER_BOOTSTRAP_Q4C_DO } from './owner-bootstrap-sql';

class Refusal extends Error {}
class Failed extends Error {}

const REPO_ROOT = resolve(__dirname, '..', '..', '..', '..', '..', '..', '..');
const TSCONFIG_APP = join(REPO_ROOT, 'packages', 'rab-server', 'tsconfig.app.json');
const DIST_ENTRY = join(REPO_ROOT, 'packages', 'rab-server', 'dist', 'database', 'typeorm', 'scripts', 'owner-login', 'bootstrap-owner-login.js');
const SOURCE_ENTRY = join(__dirname, 'bootstrap-owner-login.ts');
const MIGRATE_ENTRY = join(REPO_ROOT, 'packages', 'rab-server', 'src', 'database', 'typeorm', 'scripts', 'migrate', 'twenty', 'twenty-migrate.ts');
const RUN = `${Date.now().toString(36)}${randomBytes(2).toString('hex')}`;
const OWNER = 'crewflow_owner';
/** The schema roles the migrate child's bootstrap creates (cluster-wide): dropped with crewflow_owner between scenarios. */
const LAYOUT_ROLES = ['crewflow_worker', 'crewflow_app', 'crewflow', 'rab_app', 'rab_owner', 'rab_secure_owner'];

const log = (m: string) => process.stdout.write(`[owner-bootstrap-check] ${m}\n`);
/** 48 hex characters, re-drawn until it passes the M2 strength floor (owner-credential.ts isStrongOwnerPassword). */
const secret = (): string => {
  for (;;) {
    const v = randomBytes(24).toString('hex');
    if (isStrongOwnerPassword(v)) return v;
  }
};

/** Every secret this run created, searched for in every output (never printed). */
const SECRETS = new Set<string>();
/** Database and login names this run created: never in the child output (they may appear in the server log). */
const NAMES = new Set<string>();
const remember = <T extends string>(v: T): T => {
  SECRETS.add(v);
  return v;
};

function ident(name: string): string {
  if (!/^[a-z_][a-z0-9_]{0,62}$/.test(name)) throw new Refusal('refusing: not a plain lower-case identifier');
  return `"${name}"`;
}

interface Admin {
  url: URL;
}

function parseAdmin(raw: string | undefined): Admin {
  let url: URL;
  try {
    url = new URL(raw ?? '');
  } catch {
    throw new Refusal('MIGRATION_SECURITY_ADMIN_URL is not a valid URL');
  }
  if (!['127.0.0.1', 'localhost', '[::1]'].includes(url.hostname)) throw new Refusal('the admin URL is not a loopback disposable cluster. Refusing.');
  remember(decodeURIComponent(url.password));
  remember(url.toString());
  return { url };
}

function urlFor(admin: Admin, user: string, password: string, db: string): string {
  const u = new URL(admin.url.toString());
  u.username = user;
  u.password = encodeURIComponent(password);
  u.pathname = `/${db}`;
  u.search = '';
  return remember(u.toString());
}

type Row = Record<string, unknown>;

async function sql(admin: Admin, db: string, text: string, values: unknown[] = []): Promise<Row[]> {
  const c = createPgClientForUrl(urlFor(admin, decodeURIComponent(admin.url.username), decodeURIComponent(admin.url.password), db), 'MIGRATION_SECURITY_ADMIN_URL', { purpose: 'check' }, {});
  await c.connect();
  try {
    return (await c.query(text, values)).rows as Row[];
  } finally {
    await c.end();
  }
}

/** Sets crewflow_owner's password to a verifier of `password`, as the superuser, with the value never in statement text. */
async function setOwnerPassword(admin: Admin, password: string): Promise<void> {
  const c = createPgClientForUrl(urlFor(admin, decodeURIComponent(admin.url.username), decodeURIComponent(admin.url.password), 'postgres'), 'MIGRATION_SECURITY_ADMIN_URL', { purpose: 'check' }, {});
  await c.connect();
  try {
    await c.query(`SET log_statement = 'none'`);
    await c.query(`SET log_parameter_max_length = 0`);
    await c.query(`SELECT pg_catalog.set_config('obc.v', $1, false)`, [scramSha256Verifier(password)]);
    await c.query(`DO $$ BEGIN EXECUTE pg_catalog.format('ALTER ROLE crewflow_owner PASSWORD %L', pg_catalog.current_setting('obc.v')); END $$`);
  } finally {
    await c.end();
  }
}

async function canLogin(admin: Admin, user: string, password: string, db: string): Promise<{ ok: boolean; code: string | null; sessionUser?: string }> {
  const c = createPgClientForUrl(urlFor(admin, user, password, db), 'MIGRATION_SECURITY_ADMIN_URL', { purpose: 'check' }, {});
  c.on('error', () => undefined);
  try {
    await c.connect();
    const r = await c.query<{ s: string; u: string }>('SELECT session_user::text AS s, current_user::text AS u');
    return { ok: true, code: null, sessionUser: r.rows[0]?.s };
  } catch (error) {
    return { ok: false, code: String((error as { code?: unknown }).code ?? 'no-code') };
  } finally {
    await c.end().catch(() => undefined);
  }
}

interface OwnerState {
  exists: boolean;
  oid?: string;
  attrs?: string;
  passwordHash?: string;
  passwordIsScram?: boolean;
  memberships?: string;
  comment?: string | null;
}

async function ownerState(admin: Admin): Promise<OwnerState> {
  const rows = await sql(
    admin,
    'postgres',
    `SELECT a.oid::text AS oid,
            concat_ws(',', CASE WHEN a.rolcanlogin THEN 'LOGIN' ELSE 'NOLOGIN' END, CASE WHEN a.rolsuper THEN 'SUPERUSER' ELSE 'NOSUPERUSER' END,
              CASE WHEN a.rolbypassrls THEN 'BYPASSRLS' ELSE 'NOBYPASSRLS' END, CASE WHEN a.rolreplication THEN 'REPLICATION' ELSE 'NOREPLICATION' END,
              CASE WHEN a.rolcreatedb THEN 'CREATEDB' ELSE 'NOCREATEDB' END, CASE WHEN a.rolcreaterole THEN 'CREATEROLE' ELSE 'NOCREATEROLE' END,
              CASE WHEN a.rolinherit THEN 'INHERIT' ELSE 'NOINHERIT' END, 'VALID UNTIL ' || coalesce(a.rolvaliduntil::text, 'none')) AS attrs,
            a.rolpassword AS pw,
            pg_catalog.shobj_description(a.oid, 'pg_authid') AS comment,
            (SELECT string_agg(r.rolname, ',' ORDER BY r.rolname) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid = m.roleid WHERE m.member = a.oid) AS member_of
       FROM pg_catalog.pg_authid a WHERE a.rolname = 'crewflow_owner'`,
  );
  const r = rows[0];
  if (!r) return { exists: false };
  const pw = typeof r.pw === 'string' ? r.pw : '';
  return {
    exists: true,
    oid: String(r.oid),
    attrs: String(r.attrs),
    passwordHash: createHash('sha256').update(pw).digest('hex'),
    passwordIsScram: pw.startsWith('SCRAM-SHA-256$4096:'),
    memberships: String(r.member_of ?? ''),
    comment: r.comment === null || r.comment === undefined ? null : String(r.comment),
  };
}

/** The extensions of one database (the owner-URL mode must not create any). */
async function extensions(ctx: Ctx, db: string): Promise<string> {
  const rows = await sql(ctx.admin, db, `SELECT coalesce(string_agg(extname || ':' || extowner::regrole::text, ',' ORDER BY extname), '') AS e FROM pg_catalog.pg_extension`);
  return String(rows[0]?.e ?? '');
}

async function dbFacts(admin: Admin, db: string): Promise<{ acl: string; grant: boolean }> {
  const rows = await sql(
    admin,
    'postgres',
    `SELECT coalesce(datacl::text, '') AS acl,
            (SELECT bool_and(pg_catalog.has_database_privilege('crewflow_owner', $1, p)) FROM unnest(ARRAY['CONNECT WITH GRANT OPTION','CREATE WITH GRANT OPTION','TEMPORARY WITH GRANT OPTION']) p) AS grant
       FROM pg_catalog.pg_database WHERE datname = $1`,
    [db],
  );
  return { acl: String(rows[0]?.acl), grant: rows[0]?.grant === true };
}

const EXACT_01 = 'LOGIN,NOSUPERUSER,NOBYPASSRLS,NOREPLICATION,NOCREATEDB,CREATEROLE,INHERIT,VALID UNTIL none';
const EXACT_HARDENED = 'LOGIN,NOSUPERUSER,NOBYPASSRLS,NOREPLICATION,NOCREATEDB,NOCREATEROLE,INHERIT,VALID UNTIL none';

interface ChildRun {
  code: number | null;
  out: string;
  result: OwnerBootstrapResult | null;
}

let ENTRY = existsSync(DIST_ENTRY) ? DIST_ENTRY : SOURCE_ENTRY;

/** The db-setup inputs of one run: PG_DATABASE_URL always (crewflow_owner), PG_ADMIN_URL in modes a / b. */
interface Inputs {
  app?: string;
  admin?: string;
  extra?: Record<string, string>;
  /** Child arguments: none (db-setup) or ['--harden'] (db-harden). */
  args?: string[];
}

function baseEnv(): Record<string, string> {
  const env: Record<string, string> = {};
  for (const k of ['PATH', 'Path', 'SystemRoot', 'SYSTEMROOT', 'TEMP', 'TMP', 'HOME', 'USERPROFILE']) if (process.env[k]) env[k] = process.env[k]!;
  return env;
}

function spawnNode(argv: string[], env: Record<string, string>): Promise<{ code: number | null; out: string }> {
  return new Promise((done) => {
    const child = spawn(process.execPath, argv, { env, stdio: ['ignore', 'pipe', 'pipe'], cwd: REPO_ROOT });
    let out = '';
    child.stdout.on('data', (d) => (out += String(d)));
    child.stderr.on('data', (d) => (out += String(d)));
    child.on('close', (code) => done({ code, out }));
  });
}

async function runChild(inputs: Inputs): Promise<ChildRun> {
  // No APP_SECRET: db-setup does not receive it. No file path either: db-setup writes no file.
  // The child's two database inputs are WRITTEN into its environment (an object literal: never read from this process's).
  const env: Record<string, string> = {
    ...baseEnv(),
    NODE_ENV: 'test',
    ...(inputs.extra ?? {}),
    ...(inputs.app !== undefined ? { PG_DATABASE_URL: inputs.app } : {}),
    ...(inputs.admin !== undefined ? { PG_ADMIN_URL: inputs.admin } : {}),
  };
  const argv = [...(ENTRY.endsWith('.ts') ? [require.resolve('ts-node/dist/bin.js'), '--transpile-only', '-P', TSCONFIG_APP, ENTRY] : [ENTRY]), ...(inputs.args ?? [])];
  const { code, out } = await spawnNode(argv, env);
  const line = out.split('\n').find((l) => l.startsWith(`${OWNER_BOOTSTRAP_RESULT_PREFIX} `));
  let result: OwnerBootstrapResult | null = null;
  try {
    result = line ? (JSON.parse(line.slice(OWNER_BOOTSTRAP_RESULT_PREFIX.length + 1)) as OwnerBootstrapResult) : null;
  } catch {
    result = null;
  }
  return { code, out, result };
}

/** The REAL migrate child (twenty-migrate.ts) as crewflow_owner, exactly as rw-worker.sh's posture gate runs it. */
async function runMigrateChild(ownerUrl: string): Promise<number | null> {
  const env: Record<string, string> = { ...baseEnv(), NODE_ENV: 'development', PG_DATABASE_URL: ownerUrl, CREWFLOW_MIGRATE_ON_START: 'true' };
  const { code, out } = await spawnNode([require.resolve('ts-node/dist/bin.js'), '--transpile-only', '-P', TSCONFIG_APP, MIGRATE_ENTRY], env);
  for (const s of SECRETS) if (s && out.includes(s)) throw new Failed('a secret appeared in the migrate child output (not shown)');
  return code;
}

/** Never print the output itself: only whether a secret (or a forbidden shape) appeared. */
function assertCleanOutput(run: ChildRun): void {
  for (const s of [...SECRETS, ...NAMES]) {
    if (s && run.out.includes(s)) throw new Failed('a secret, URL, database name or login name appeared in the child output (not shown)');
  }
  if (/postgres(ql)?:\/\/[^\s)]*@/i.test(run.out)) throw new Failed('a URL shape appeared in the child output (not shown)');
  if (run.out.includes('SCRAM-SHA-256$')) throw new Failed('a verifier appeared in the child output (not shown)');
  if (/\n\s+at /.test(run.out)) throw new Failed('a stack trace appeared in the child output');
}

function expect(cond: unknown, what: string): void {
  if (!cond) throw new Failed(what);
}

function expectResult(run: ChildRun, exitCode: number, outcome: OwnerBootstrapResult['outcome'], what: string, createRole?: OwnerBootstrapResult['createRole']): void {
  expect(run.code === exitCode, `${what}: exit ${run.code}, expected ${exitCode} (${run.result?.outcome ?? 'none'} ${run.result?.code ?? ''})`);
  expect(run.result?.outcome === outcome, `${what}: outcome ${run.result?.outcome ?? 'none'}, expected ${outcome}`);
  expect(run.result?.exitCode === exitCode, `${what}: result exitCode mismatch`);
  if (createRole) expect(run.result?.createRole === createRole, `${what}: createRole ${run.result?.createRole ?? 'none'}, expected ${createRole}`);
}

function expectLine(run: ChildRun, message: string, what: string): void {
  expect(run.out.includes(message), `${what}: the expected fixed message is missing`);
}

interface Ctx {
  admin: Admin;
  suUser: string;
  suPassword: string;
  dbs: string[];
  roles: string[];
  serverVersionNum: number;
}

async function createDb(ctx: Ctx, tag: string, owner?: string): Promise<string> {
  const db = `obc_${tag}_${RUN}`;
  await sql(ctx.admin, 'postgres', `CREATE DATABASE ${ident(db)}${owner ? ` OWNER ${ident(owner)}` : ''}`);
  ctx.dbs.push(db);
  NAMES.add(db);
  return db;
}

async function createAdminRole(ctx: Ctx, tag: string, attrs: string): Promise<{ name: string; password: string }> {
  const name = `obc_${tag}_${RUN}`;
  const password = remember(secret());
  await sql(ctx.admin, 'postgres', `CREATE ROLE ${ident(name)} ${attrs}`);
  const c = createPgClientForUrl(urlFor(ctx.admin, ctx.suUser, ctx.suPassword, 'postgres'), 'MIGRATION_SECURITY_ADMIN_URL', { purpose: 'check' }, {});
  await c.connect();
  try {
    await c.query(`SET log_statement = 'none'`);
    await c.query(`SELECT pg_catalog.set_config('obc.v', $1, false)`, [scramSha256Verifier(password)]);
    await c.query(`DO $$ BEGIN EXECUTE pg_catalog.format('ALTER ROLE %I PASSWORD %L', '${name}', pg_catalog.current_setting('obc.v')); END $$`);
  } finally {
    await c.end();
  }
  ctx.roles.push(name);
  NAMES.add(name);
  return { name, password };
}

/** Back to "no crewflow_owner": drop this run's databases first, then the schema roles and crewflow_owner, then this run's other roles. */
async function reset(ctx: Ctx): Promise<void> {
  for (const db of ctx.dbs.splice(0)) await sql(ctx.admin, 'postgres', `DROP DATABASE IF EXISTS ${ident(db)} WITH (FORCE)`);
  // One statement: memberships among these roles (the migrate child's bootstrap grants them) go with them.
  await sql(ctx.admin, 'postgres', `DROP ROLE IF EXISTS ${[...LAYOUT_ROLES, OWNER].map(ident).join(', ')}`);
  for (const role of ctx.roles.splice(0).reverse()) await sql(ctx.admin, 'postgres', `DROP ROLE IF EXISTS ${ident(role)}`);
}

/** crewflow_owner made by the SUPERUSER with the 01 attributes (+ extra), the grant, and a password. */
async function presetOwner(ctx: Ctx, db: string, extra: string, password: string): Promise<void> {
  // The 01 attributes with `extra` replacing its counterpart (SUPERUSER replaces NOSUPERUSER, NOLOGIN replaces LOGIN, ...).
  const base = ['LOGIN', 'NOSUPERUSER', 'NOBYPASSRLS', 'NOREPLICATION', 'NOCREATEDB', 'CREATEROLE', 'INHERIT'];
  const bare = (a: string) => a.replace(/^NO/, '');
  const attrs = extra ? [...base.filter((a) => bare(a) !== bare(extra)), extra] : base;
  if (!attrs.every((a) => /^[A-Z]+$/.test(a))) throw new Refusal('refusing: not a role attribute');
  await sql(ctx.admin, 'postgres', `CREATE ROLE crewflow_owner ${attrs.join(' ')}`);
  await sql(ctx.admin, 'postgres', `GRANT CONNECT, CREATE, TEMPORARY ON DATABASE ${ident(db)} TO crewflow_owner WITH GRANT OPTION`);
  await setOwnerPassword(ctx.admin, password);
}

/**
 * The CREATEROLE mark, set as the superuser the way own-database-app-login.sql does in mode c: the prefix and a unix expiry
 * the SERVER computes as now + `offsetSeconds` (default: the 24 h grace period; negative = already expired).
 */
async function markPending(ctx: Ctx, offsetSeconds: number = OWNER_CREATEROLE_GRACE_SECONDS): Promise<void> {
  if (!Number.isInteger(offsetSeconds)) throw new Refusal('refusing: not an integer offset');
  await sql(
    ctx.admin,
    'postgres',
    `DO $m$ BEGIN EXECUTE pg_catalog.format('COMMENT ON ROLE crewflow_owner IS %L', '${OWNER_CREATEROLE_MARK_PREFIX}' || (pg_catalog.date_part('epoch', pg_catalog.now())::bigint + (${offsetSeconds}))::text); END $m$`,
  );
}

/** The server clock, unix seconds (the mark's expiry is judged by it, never by this process's clock). */
async function dbNow(ctx: Ctx): Promise<number> {
  return Number((await sql(ctx.admin, 'postgres', `SELECT pg_catalog.date_part('epoch', pg_catalog.now())::bigint AS t`))[0]?.t);
}

/** The unix expiry of a valid mark (prefix + 1-12 digits), or null for anything else. */
function markExpiry(comment: string | null | undefined): number | null {
  if (typeof comment !== 'string' || !comment.startsWith(OWNER_CREATEROLE_MARK_PREFIX)) return null;
  const rest = comment.slice(OWNER_CREATEROLE_MARK_PREFIX.length);
  return /^[0-9]{1,12}$/.test(rest) ? Number(rest) : null;
}

/** A mark just written by the server: valid, and its expiry is db now + 24 h (within [-120 s, +5 s]). */
async function expectFreshMark(ctx: Ctx, comment: string | null | undefined, label: string): Promise<number> {
  const expiry = markExpiry(comment);
  expect(expiry !== null, `${label}: the CREATEROLE mark is not "${OWNER_CREATEROLE_MARK_PREFIX}<unix expiry>"`);
  const target = (await dbNow(ctx)) + OWNER_CREATEROLE_GRACE_SECONDS;
  expect((expiry as number) >= target - 120 && (expiry as number) <= target + 5, `${label}: the mark's expiry is not the server's now + ${OWNER_CREATEROLE_GRACE_SECONDS} s`);
  return expiry as number;
}

/**
 * A ledger that says "complete" for THIS image (every migration file's name), owned by crewflow_owner: the cheap stand-in
 * for a migrated database in the scenarios that are not about the migration itself. The CREATEROLE lifecycle scenario
 * uses the real migrate child instead.
 */
async function fakeCompleteLedger(ctx: Ctx, db: string): Promise<void> {
  const names = imageMigrationNames();
  expect(names.length > 100, `this image lists only ${names.length} migration files`);
  await sql(ctx.admin, db, `CREATE SCHEMA core AUTHORIZATION crewflow_owner`);
  await sql(ctx.admin, db, `CREATE TABLE core.migrations (id serial PRIMARY KEY, "timestamp" bigint NOT NULL, name varchar NOT NULL)`);
  await sql(ctx.admin, db, `INSERT INTO core.migrations ("timestamp", name) SELECT pg_catalog.right(n, 13)::bigint, n FROM pg_catalog.unnest($1::text[]) AS n`, [names]);
  await sql(ctx.admin, db, `ALTER TABLE core.migrations OWNER TO crewflow_owner`);
}

/** The boot gate's CREATEROLE rule, in production, on a real crewflow_owner session: refused (true) or the warnings. */
async function bootCreateRoleRule(ctx: Ctx, password: string, db: string): Promise<{ refused: boolean; warnings: string[]; message: string }> {
  const c = createPgClientForUrl(urlFor(ctx.admin, OWNER, password, db), 'the crewflow_owner session', { purpose: 'check' }, {});
  await c.connect();
  let row: Row | undefined;
  try {
    row = (await c.query(BOOT_FACTS_SQL)).rows[0] as Row | undefined;
  } finally {
    await c.end();
  }
  try {
    return { refused: false, warnings: assertCreateRoleGate(parseBootFacts(row), true, 'api process'), message: '' };
  } catch (error) {
    if (error instanceof DatabaseBootGateError) return { refused: true, warnings: [], message: error.message };
    throw error;
  }
}

interface Scenario {
  id: string;
  covers: string;
  run(ctx: Ctx): Promise<string[]>;
}

const suUrl = (ctx: Ctx, db: string) => urlFor(ctx.admin, ctx.suUser, ctx.suPassword, db);
const ownerUrl = (ctx: Ctx, password: string, db: string) => urlFor(ctx.admin, OWNER, password, db);

/** Mode b fresh: created with the env password (SCRAM), the 01 attributes, the grant, CREATEROLE marked (schema incomplete). */
async function assertFreshCreated(ctx: Ctx, db: string, adminUrl: string, label: string): Promise<{ state: OwnerState; acl: string; password: string }> {
  const password = remember(secret());
  const run = await runChild({ admin: adminUrl, app: ownerUrl(ctx, password, db) });
  assertCleanOutput(run);
  expectResult(run, 0, 'created', label, 'marked');
  expect(run.result?.passwordSet === true && run.result.grantAdded === true, `${label}: wrong flags`);
  expectLine(run, OWNER_BOOTSTRAP_MESSAGES.createRoleMarked, label);
  const state = await ownerState(ctx.admin);
  expect(state.exists && state.attrs === EXACT_01, `${label}: attributes are not exactly the 01 attributes`);
  expect(state.passwordIsScram, `${label}: rolpassword is not a SCRAM-SHA-256 verifier`);
  await expectFreshMark(ctx, state.comment, label);
  const facts = await dbFacts(ctx.admin, db);
  expect(facts.grant, `${label}: CONNECT/CREATE/TEMPORARY WITH GRANT OPTION missing`);
  const login = await canLogin(ctx.admin, OWNER, password, db);
  expect(login.ok && login.sessionUser === OWNER, `${label}: the env password (PG_DATABASE_URL) does not log in as crewflow_owner`);
  return { state, acl: facts.acl, password };
}

/** A later start with the same env: nothing in the database changes. */
async function assertRestartUnchanged(ctx: Ctx, db: string, adminUrl: string, before: { state: OwnerState; acl: string; password: string }, label: string): Promise<void> {
  const run = await runChild({ admin: adminUrl, app: ownerUrl(ctx, before.password, db) });
  assertCleanOutput(run);
  expectResult(run, 0, 'unchanged', label, 'kept');
  const after = await ownerState(ctx.admin);
  expect(JSON.stringify(after) === JSON.stringify(before.state), `${label}: the role changed (oid, password, attributes, memberships or comment)`);
  expect((await dbFacts(ctx.admin, db)).acl === before.acl, `${label}: database ACL changed`);
}

/** A different password in PG_DATABASE_URL, with the admin: set to it (same role), the old one no longer logs in. */
async function assertPasswordSet(ctx: Ctx, db: string, adminUrl: string, before: { state: OwnerState; password: string }, label: string): Promise<string> {
  const next = remember(secret());
  const run = await runChild({ admin: adminUrl, app: ownerUrl(ctx, next, db) });
  assertCleanOutput(run);
  expectResult(run, 0, 'updated', label);
  expect(run.result?.passwordSet === true && run.result.created === false, `${label}: wrong flags`);
  expectLine(run, OWNER_BOOTSTRAP_MESSAGES.passwordSet, label);
  const after = await ownerState(ctx.admin);
  expect(after.oid === before.state.oid && after.attrs === before.state.attrs, `${label}: the role was recreated or its attributes changed`);
  expect(after.passwordHash !== before.state.passwordHash && after.passwordIsScram, `${label}: rolpassword not replaced by a SCRAM verifier`);
  expect((await canLogin(ctx.admin, OWNER, next, db)).ok, `${label}: the new env password does not log in`);
  expect(!(await canLogin(ctx.admin, OWNER, before.password, db)).ok, `${label}: the old password still logs in`);
  return next;
}

